cat > /workspace/src/main.rs << 'EOFMAIN'
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;
use std::io::Write;

mod config;
mod crypto;
mod log_parser;
mod ui;

use config::Config;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Parse command line arguments
    let mut help = false;
    let mut config_path: Option<PathBuf> = None;
    let mut log_dir_path: Option<PathBuf> = None;
    let mut log_name_format: Option<String> = None;
    let mut sunday_start = false;
    let mut first_line_section = false;
    let mut password: Option<String> = None;
    let mut encrypt = false;
    let mut decrypt = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => help = true,
            "-c" | "--config" => {
                i += 1;
                if i < args.len() {
                    config_path = Some(PathBuf::from(&args[i]));
                }
            }
            "--log-dir-path" => {
                i += 1;
                if i < args.len() {
                    log_dir_path = Some(PathBuf::from(&args[i]));
                }
            }
            "--log-name-format" => {
                i += 1;
                if i < args.len() {
                    log_name_format = Some(args[i].clone());
                }
            }
            "--sunday-start" => sunday_start = true,
            "--first-line-section" => first_line_section = true,
            "--password" => {
                i += 1;
                if i < args.len() {
                    password = Some(args[i].clone());
                }
            }
            "--encrypt" => encrypt = true,
            "--decrypt" => decrypt = true,
            _ => {}
        }
        i += 1;
    }

    if help {
        print_help();
        return;
    }

    // Load config
    let default_config_path = dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join(".caps-log")
        .join("config.ini");

    let config_file = config_path.as_ref().unwrap_or(&default_config_path);

    let mut config = if config_file.exists() {
        match config::Config::from_file(config_file) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Captain's log encountered an error: \n Failed to open file: {}", config_file.display());
                process::exit(1);
            }
        }
    } else {
        config::Config::default()
    };

    // Override config with command line arguments
    if let Some(p) = log_dir_path {
        config.log_dir_path = p;
    }
    if let Some(f) = log_name_format {
        config.log_name_format = f;
    }
    if sunday_start {
        config.sunday_start = true;
    }
    if first_line_section {
        config.first_line_section = true;
    }
    if let Some(p) = password {
        config.password = Some(p);
    }

    // Ensure log directory exists
    if !config.log_dir_path.exists() {
        std::fs::create_dir_all(&config.log_dir_path).ok();
    }

    if encrypt {
        if let Some(pass) = &config.password {
            println!("Applying crypto...");
            crypto::encrypt_logs(&config.log_dir_path, pass, &config.log_name_format).ok();
        } else {
            eprintln!("Error: --password is required for encryption");
            process::exit(1);
        }
        return;
    }

    if decrypt {
        if let Some(pass) = &config.password {
            println!("Applying crypto...");
            crypto::decrypt_logs(&config.log_dir_path, pass, &config.log_name_format).ok();
        } else {
            eprintln!("Error: --password is required for decryption");
            process::exit(1);
        }
        return;
    }

    // Check if logs are encrypted
    let cle_path = config.log_dir_path.join(".cle");
    if cle_path.exists() && config.password.is_none() {
        // Prompt for password
        println!("Enter password for log files:");
        let mut password = String::new();
        if std::io::stdin().read_line(&mut password).is_ok() {
            password = password.trim().to_string();
            config.password = Some(password);
        }
    }

    // Launch TUI
    ui::run(&config).ok();
}

fn print_help() {
    println!("Captain's Log (caps-log)! A CLI journalig tool.");
    println!("Version: commit-93cc85d16ab60ba8d646458fe0233778317b22a3");
    println!("Allowed options:");
    println!("  -h [ --help ]         show this message");
    println!("  -c [ --config ] arg   override the default config file path");
    println!("                        (~/.caps-log/config.ini)");
    println!("  --log-dir-path arg    path where log files are stored");
    println!("  --log-name-format arg format in which log entry markdown files are saved");
    println!("  --sunday-start        have the calendar display sunday as first day of the");
    println!("                        week");
    println!("  --first-line-section  override the default behaviour of ignoring sections");
    println!("                        (lines starting with `#`) in the first line of a log");
    println!("                        entry file");
    println!("  --password arg        password for encrypted log repositories or to be used");
    println!("                        with --encrypt/--decrypt");
    println!("  --encrypt             apply encryption to all logs in log dir path (needs");
    println!("                        --password)");
    println!("  --decrypt             apply decryption to all logs in log dir path (needs");
    println!("                        --password)");
}

mod dirs {
    use std::path::PathBuf;

    pub fn config_dir() -> Option<PathBuf> {
        if let Ok(home) = std::env::var("HOME") {
            Some(PathBuf::from(home))
        } else {
            None
        }
    }
}
EOFMAIN

