use std::io::Result as IoResult;

#[derive(Clone, Debug)]
pub struct Config {
    pub log_dir_path: PathBuf,
    pub log_name_format: String,
    pub sunday_start: bool,
    pub first_line_section: bool,
    pub password: Option<String>,
}

impl Config {
    pub fn default() -> Self {
        let home = std::env::var("HOME").unwrap_or_else(|_| ".".to_string());
        Config {
            log_dir_path: PathBuf::from(format!("{}/.caps-log/day/", home)),
            log_name_format: "d%y_%m_%d.md".to_string(),
            sunday_start: false,
            first_line_section: false,
            password: None,
        }
    }

    pub fn from_file(path: &PathBuf) -> IoResult<Self> {
        let content = fs::read_to_string(path)?;
        let mut config = Config::default();

        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
                continue;
            }

            if let Some((key, value)) = line.split_once('=') {
                let key = key.trim();
                let value = value.trim();

                match key {
                    "log-dir-path" => {
                        config.log_dir_path = PathBuf::from(value);
                    }
                    "log-filename-format" | "log-name-format" => {
                        config.log_name_format = value.to_string();
                    }
                    "sunday-start" => {
                        config.sunday_start = value.to_lowercase() == "true";
                    }
                    "first-line-section" => {
                        config.first_line_section = value.to_lowercase() == "true";
                    }
                    "password" => {
                        config.password = Some(value.to_string());
                    }
                    _ => {}
                }
            }
        }

        Ok(config)
    }
}
