pub struct LogEntry {
    pub date: String,
    pub sections: Vec<Section>,
    pub tags: Vec<String>,
}

#[derive(Debug, Clone)]
pub struct Section {
    pub name: String,
    pub tags: Vec<String>,
    pub content: String,
}

pub fn parse_log_file(path: &Path) -> std::io::Result<LogEntry> {
    let content = fs::read_to_string(path)?;
    let mut entry = LogEntry {
        date: String::new(),
        sections: vec![],
        tags: vec![],
    };

    let lines: Vec<&str> = content.lines().collect();
    let mut current_section: Option<Section> = None;
    let mut first_line = true;

    for line in lines {
        if first_line {
            entry.date = line.to_string();
            first_line = false;
            continue;
        }

        if line.starts_with("# ") {
            // Section header
            if let Some(section) = current_section {
                entry.sections.push(section);
            }
            let name = line[2..].to_string();
            current_section = Some(Section {
                name,
                tags: vec![],
                content: String::new(),
            });
        } else if line.starts_with("* ") {
            // Tag
            let tag = line[2..].to_string();
            if let Some(ref mut section) = current_section {
                section.tags.push(tag.clone());
            }
            entry.tags.push(tag);
        }
    }

    if let Some(section) = current_section {
        entry.sections.push(section);
    }

    Ok(entry)
}
