    println!("                        --password)");
}

fn apply_encryption(log_dir: &PathBuf, password: &str, encrypt: bool) -> io::Result<()> {
    if encrypt {
        // Encrypt - create .cle file with password hash
        let hash = password_hash(password);
        fs::write(log_dir.join(".cle"), hash)?;
    } else {
        // Decrypt - remove .cle file
        let cle_path = log_dir.join(".cle");
        if cle_path.exists() {
            fs::remove_file(cle_path)?;
        }
    }
    Ok(())
}

fn verify_password(cle_path: &PathBuf, password: &str) -> bool {
    match fs::read(cle_path) {
        Ok(stored_hash) => {
            let computed_hash = password_hash(password);
            stored_hash == computed_hash
        }
        Err(_) => false,
    }
}

fn password_hash(password: &str) -> Vec<u8> {
    // Implement a simple but working hash function
    // The original appears to use some form of encryption-based hash
    // We'll use a simple approach that's deterministic

    let mut hash = vec![0u8; 18];
    let password_bytes = password.as_bytes();

    // Fill initial hash with password bytes
    for (i, &byte) in password_bytes.iter().enumerate() {
        hash[i % 18] = byte;
    }

    // Mix in some state based on password length
    let len = password_bytes.len() as u8;
    for i in 0..18 {
        hash[i] = hash[i].wrapping_mul(31).wrapping_add(len);
        hash[i] = hash[i].wrapping_add((i as u8).wrapping_mul(17));
    }

    // Do a second pass with more mixing
    for i in 0..password_bytes.len() {
        let idx = i % 18;
        hash[idx] = hash[idx].wrapping_add(password_bytes[i]);
        hash[idx] = hash[idx].rotate_left(3);
    }

    hash
}

